import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { spawn, spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

const repo = 'D:/ClaudeProjects/ai_acknowladge';
const sourcePath = fileURLToPath(import.meta.url);
const source = fs.readFileSync(sourcePath, 'utf8');
const sha = value => crypto.createHash('sha256').update(value).digest('hex');
const recoveryFile = 'docs/验收证据/story-2-2-wsl-recovery-2026-09-12T09-22-02-992Z.json';
const recovery = JSON.parse(fs.readFileSync(path.join(repo, recoveryFile), 'utf8'));
const report = {
  story: '2.2', recorded_at: new Date().toISOString(), status: 'failed',
  scope: '已批准的重启后管理员只读预检；连续两次连接保留同一根 shell，不暂停进程、不写时钟参数。',
  source_file: path.basename(sourcePath), source_sha256: sha(source), maintenance_source: source,
  recovery_evidence: recoveryFile, recovery_evidence_sha256: sha(fs.readFileSync(path.join(repo, recoveryFile))),
  expected_boot_id: recovery.after.boot_id, connections: [], signals_sent: [], clock_writes: [],
};
const evidencePath = path.join(repo, 'docs/验收证据/story-2-2-root-channel-' + report.recorded_at.replace(/[:.]/g, '-') + '.json');
const livePath = sourcePath.replace(/\.mjs$/, '.live.json');
if (fs.existsSync(livePath) || fs.existsSync(evidencePath)) throw new Error('记录已存在');
const save = () => fs.writeFileSync(livePath, JSON.stringify(report, null, 2) + '\n');
const clean = bytes => bytes.toString('utf8').replaceAll('\0', '').replace(/\u001b\[[0-9;?]*[A-Za-z]/g, '').replaceAll('\r', '');

async function roundTrip(commands) {
  const marker = 'A2_DONE_' + crypto.randomBytes(12).toString('hex');
  const delimiter = 'A2_SCRIPT_' + crypto.randomBytes(12).toString('hex');
  const input = 'zhiliao_a2_tty=$(stty -g); stty -echo\n' +
    'printf "A2_SHELL_PID=%s\\n" "$$"\n' +
    "/bin/sh <<'" + delimiter + "'\n" + commands + '\n' + delimiter + '\n' +
    'zhiliao_a2_status=$?; stty "$zhiliao_a2_tty"; printf "\\n' + marker + ':%s\\n" "$zhiliao_a2_status"; unset zhiliao_a2_tty zhiliao_a2_status\n';
  const started = performance.now();
  const child = spawn('C:/Windows/System32/wsl.exe', ['--debug-shell'], {
    cwd: repo, windowsHide: true, stdio: ['pipe', 'pipe', 'pipe'],
  });
  const output = [], errors = [];
  let sent = false, matched = false, code, failure, closeTimer;
  const deadline = setTimeout(() => { failure = sent ? '命令未在 30 秒内完成' : '未在 30 秒内收到真实 shell 提示符'; child.kill(); }, 30000);
  child.stdout.on('data', chunk => {
    output.push(chunk);
    const bytes = Buffer.concat(output);
    if (bytes.length > 1024 * 1024) { failure = '输出超出预算'; child.kill(); return; }
    const text = clean(bytes);
    if (!sent && /(?:^|\n)root@[^\n]*[#$] ?$/.test(text)) {
      sent = true;
      child.stdin.write(Buffer.from(input, 'utf8'));
    }
    const completion = text.split('\n').find(line => line.startsWith(marker + ':'));
    if (!matched && completion && /^\d+$/.test(completion.slice(marker.length + 1))) {
      matched = true;
      code = Number(completion.slice(marker.length + 1));
      clearTimeout(deadline);
      closeTimer = setTimeout(() => child.kill(), 150);
    }
  });
  child.stderr.on('data', chunk => errors.push(chunk));
  child.stdin.on('error', error => { failure ??= error.message; });
  const closed = await new Promise(resolve => {
    child.on('error', error => { failure = error.message; resolve({code: null, signal: null}); });
    child.on('close', (code, signal) => resolve({code, signal}));
  });
  clearTimeout(deadline);
  clearTimeout(closeTimer);
  const stdout = clean(Buffer.concat(output));
  const entry = {
    at: new Date().toISOString(), elapsed_ms: performance.now() - started,
    prompt_received_before_commands: sent, completion_marker_matched: matched, shell_command_exit_code: code,
    forwarding_process: {pid: child.pid, ...closed}, shell_pid: stdout.match(/(?:^|\n)A2_SHELL_PID=(\d+)/)?.[1],
    disconnect: '仅结束本次 Windows wsl.exe 转发进程；未向 Linux 根 shell 发送 exit 或 EOF',
    requested_stdin: input, stdout, stderr: clean(Buffer.concat(errors)), error: failure,
  };
  report.connections.push(entry);
  save();
  if (!sent || !matched || code !== 0 || failure) throw new Error(failure ?? '根通道命令未正常完成');
  return entry;
}

const pythonProbe = String.raw`import os, json, signal, time
def read_proc(name):
    fd = os.open(name, os.O_RDONLY, dir_fd=3)
    try:
        chunks = []
        while True:
            data = os.read(fd, 65536)
            if not data: break
            chunks.append(data)
        return b''.join(chunks)
    finally:
        os.close(fd)
def link(name):
    return os.readlink(name, dir_fd=3)
root_ns = link('1/ns/pid')
self_ns = link(str(os.getpid()) + '/ns/pid')
assert os.geteuid() == 0 and self_ns == root_ns
entries = []
for name in os.listdir(3):
    if not name.isdigit(): continue
    try:
        if read_proc(name + '/comm').decode().strip() != 'chronyd': continue
        raw_stat = read_proc(name + '/stat').decode().strip()
        stat_parts = raw_stat.rsplit(') ', 1)[1].split()
        cmdline = [x.decode() for x in read_proc(name + '/cmdline').split(b'\0') if x]
        exe = link(name + '/exe')
        metadata = os.stat(name + '/exe', dir_fd=3)
        config_path = '/etc/chrony.conf'
        for i, value in enumerate(cmdline[1:], 1):
            if value == '-f': config_path = cmdline[i + 1]
            elif value.startswith('-f') and len(value) > 2: config_path = value[2:]
        config = read_proc(name + '/root' + config_path).decode()
        pidfd = os.pidfd_open(int(name))
        os.close(pidfd)
        entries.append({'pid': int(name), 'exe': exe, 'cmdline': cmdline,
            'state': stat_parts[0], 'ppid': int(stat_parts[1]), 'start_ticks': stat_parts[19],
            'pid_namespace': link(name + '/ns/pid'), 'mount_namespace': link(name + '/ns/mnt'),
            'exe_metadata': {'device': metadata.st_dev, 'inode': metadata.st_ino, 'size': metadata.st_size, 'mtime_ns': str(metadata.st_mtime_ns)},
            'raw_stat': raw_stat, 'status': read_proc(name + '/status').decode(),
            'configuration_path': config_path, 'configuration': config, 'pidfd_open_verified': True})
    except FileNotFoundError:
        continue
assert len(entries) == 1
entry = entries[0]
assert entry['exe'] == '/usr/sbin/chronyd' and entry['ppid'] == 1 and entry['pid_namespace'] == root_ns
assert entry['state'] not in ('T', 't', 'Z', 'X')
result = {'root_pid_namespace': root_ns, 'python_pid_namespace': self_ns,
    'root_proc_fd_verified': True, 'python_pid': os.getpid(), 'uid': os.geteuid(),
    'pidfd_send_signal_available': hasattr(signal, 'pidfd_send_signal'),
    'boot_id': read_proc('sys/kernel/random/boot_id').decode().strip(),
    'python_version': os.sys.version, 'chronyd': entry,
    'clocksource': open('/sys/devices/system/clocksource/clocksource0/current_clocksource').read().strip(),
    'phc_clock_name': open('/sys/class/ptp/ptp0/clock_name').read().strip(),
    'raw_ns': str(time.clock_gettime_ns(time.CLOCK_MONOTONIC_RAW))}
print('A2_IDENTITY_JSON=' + json.dumps(result), flush=True)
`;
report.python_probe = pythonProbe;
report.python_probe_sha256 = sha(pythonProbe);

try {
  if (recovery.status !== 'restored' || !recovery.preservation.passed) throw new Error('恢复证据未通过');
  const ubuntu = spawnSync('wsl.exe', ['-d', 'Ubuntu-24.04', '-u', 'root', '--', 'readlink', '/proc/self/ns/pid'], {
    cwd: repo, windowsHide: true, encoding: 'utf8', timeout: 15000,
  });
  report.ubuntu_namespace = ubuntu.stdout.trim();
  if (ubuntu.status !== 0 || !/^pid:\[\d+\]$/.test(report.ubuntu_namespace)) throw new Error('无法核对 Ubuntu 命名空间');
  save();
  await roundTrip('set -eu\nid\nprintf "A2_BOOT=%s\\n" "$(cat /proc/sys/kernel/random/boot_id)"\nreadlink /proc/1/ns/pid\nreadlink /proc/self/ns/pid\ncat /proc/1/comm');
  const commands = `set -eu
printf 'CHRONY_VERSION\n'
/sbin/chronyd -v
printf 'CHRONY_PRINT_CONFIGURATION\n'
/sbin/chronyd -p
printf 'CHRONY_TRACKING\n'
chronyc -n tracking
zhiliao_a2_base=''
for entry in /proc/[0-9]*/ns/pid; do
  ns=$(readlink "$entry") || continue
  if [ "$ns" = '${report.ubuntu_namespace}' ]; then
    base=$(dirname "$(dirname "$entry")")
    if [ -x "$base/root/usr/bin/python3" ]; then
      zhiliao_a2_base="$base"
      break
    fi
  fi
done
test -n "$zhiliao_a2_base"
printf 'A2_UBUNTU_ROOT=%s\\n' "$zhiliao_a2_base/root"
chroot "$zhiliao_a2_base/root" /usr/bin/python3 - 3</proc <<'A2_PYTHON_READONLY'
${pythonProbe}
A2_PYTHON_READONLY
`;
  const second = await roundTrip(commands);
  const identityLine = second.stdout.split('\n').find(line => line.startsWith('A2_IDENTITY_JSON='));
  if (!identityLine) throw new Error('缺少根进程结构化身份结果');
  report.identity = JSON.parse(identityLine.slice('A2_IDENTITY_JSON='.length));
  report.ubuntu_root_from_kernel = second.stdout.match(/(?:^|\n)A2_UBUNTU_ROOT=(.+)/)?.[1];
  if (report.identity.boot_id !== report.expected_boot_id) throw new Error('内核启动标识发生变化');
  if (!report.connections[0].shell_pid || report.connections[0].shell_pid !== second.shell_pid) throw new Error('两次连接未核实为同一根 shell');
  report.same_root_shell_reconnected = true;
  report.status = 'passed';
} catch (error) {
  report.error = error.message;
} finally {
  report.finished_at = new Date().toISOString();
  fs.writeFileSync(evidencePath, JSON.stringify(report, null, 2) + '\n', {flag: 'wx'});
  report.evidence_path = path.relative(repo, evidencePath).replaceAll('\\', '/');
  save();
}
process.exitCode = report.status === 'passed' ? 0 : 1;
